"use client";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisHowItWorksContent } from "./components/how-it-works/content";
import View1 from "./components/how-it-works/variants/02-process-grid";
const variants = {"process-grid":View1};
export type { ArtemisHowItWorksContent, ArtemisHowItWorksLink, ArtemisHowItWorksStep } from "./components/how-it-works/content";
export interface ArtemisHowItWorksProps { className?: string; variant?: "process-grid"; /** The words on the how-it-works section; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisHowItWorksContent>; }
export function ArtemisHowItWorks({ className, variant = "process-grid", content }: ArtemisHowItWorksProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}

// @zeus-internal
import type { ComponentType } from "react";

/** The words on a link or button, and where it goes. */
export interface ArtemisHowItWorksLink {
  label: string;
  href: string;
}

/** One step of the process. Layouts number the steps in order and draw their own scene for each one. */
export interface ArtemisHowItWorksStep {
  /** A short label over the title, such as "Collect". All layouts. Keep labels unique, since story-stack and card-deck tell steps apart by it. */
  label: string;
  /** The step's title. All layouts. */
  title: string;
  /** A sentence or two under the title. All layouts; card-deck shows two lines of it. */
  description: string;
  /** The step's icon. centered-cards, process-grid, walkthrough and card-deck, which keep their own icon for that slot when you leave this out. */
  icon?: ComponentType<{ className?: string }>;
}

/** The words on an Artemis how-it-works section. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisHowItWorksContent {
  /** The small pill over the headline. All layouts. */
  badge: string;
  /** The heading. All layouts; process-grid, story-stack, walkthrough and card-deck break it into two lines at the middle word. */
  headline: string;
  /** A line or two beside or under the headline. All layouts. */
  subhead: string;
  /** The button after the steps or beside the subhead. centered-cards, process-grid, story-stack and walkthrough. */
  cta?: ArtemisHowItWorksLink;
  /** The steps, in order. All layouts; three look best, and card-deck's own list has four. */
  steps: ArtemisHowItWorksStep[];
}

"use client";
// @zeus-internal
import { ArrowRight, MessageSquareText, Rocket, Rows3 } from "lucide-react";
import { motion, useInView, useReducedMotion } from "motion/react";
import { type ComponentType, useEffect, useRef, useState } from "react";
import { ArtemisButton, ArtemisButtonLink } from "../../../foundations/button";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import { artemisCx } from "../../../lib/utils";
import type { ArtemisHowItWorksContent, ArtemisHowItWorksStep } from "../content";
import { CaptureScene, ShapeScene, ShipScene } from "./02-process-grid/scenes";
const AUTOPLAY_MS = 6400;
const defaultSteps: ArtemisHowItWorksStep[] = [
    {
        label: "Capture",
        title: "Bring the signal into focus",
        description: "Collect customer notes, requests, and loose ideas in one brief that keeps the original context intact.",
    },
    {
        label: "Shape",
        title: "Turn context into a clear plan",
        description: "Organize the brief into decisions, owners, and the next work that will move the outcome forward.",
    },
    {
        label: "Ship",
        title: "Move the right version live",
        description: "Review the final details, publish with confidence, and keep the result visible to everyone involved.",
    },
];
const DEFAULT = {
    badge: "How it works",
    headline: "One clear path from raw input to release.",
    subhead: "Capture what matters, shape it into an aligned plan, and move it live without losing the thinking that got you there.",
    cta: { label: "See the workflow", href: "#" },
    steps: defaultSteps,
} satisfies ArtemisHowItWorksContent;
/** The icon and scene for each slot, in turn; a step without an icon keeps its slot's. */
const ICONS = [MessageSquareText, Rows3, Rocket];
const SCENES = [CaptureScene, ShapeScene, ShipScene];
const WORD_HIDDEN = { opacity: 0, filter: "blur(10px)", y: "24%" };
const WORD_SHOWN = { opacity: 1, filter: "blur(0px)", y: "0%" };
function wordTransition(index: number) {
    const delay = index * 0.065;
    return {
        opacity: { duration: 0.7, ease: ARTEMIS_EASE_OUT, delay },
        filter: { duration: 0.9, ease: ARTEMIS_EASE_OUT, delay },
        y: { type: "spring", stiffness: 70, damping: 13, mass: 0.6, delay },
    } as const;
}
const INSTANT = { duration: 0 } as const;
const COPY_HIDDEN = { opacity: 0, filter: "blur(7px)", transform: "translate3d(0,12px,0)" };
const COPY_SHOWN = { opacity: 1, filter: "blur(0px)", transform: "translate3d(0,0,0)" };
const CORNER = "art:pointer-events-none art:absolute art:z-20 art:size-4 art:before:absolute art:before:top-1/2 art:before:left-0 art:before:h-px art:before:w-full art:before:-translate-y-1/2 art:before:bg-foreground/20 art:after:absolute art:after:top-0 art:after:left-1/2 art:after:h-full art:after:w-px art:after:-translate-x-1/2 art:after:bg-foreground/20";
function stepNumber(index: number) {
    return String(index + 1).padStart(2, "0");
}
function Heading({ text }: {
    text: string;
}) {
    const ref = useRef<HTMLHeadingElement>(null);
    const inView = useInView(ref, { once: true, amount: 0.4 });
    const reduce = useReducedMotion();
    const words = text.split(" ");
    const lines = [words.slice(0, Math.floor(words.length / 2)), words.slice(Math.floor(words.length / 2))];
    return (<h2 ref={ref} className="art:block art:mt-7 art:max-w-4xl art:text-balance art:tracking-[-0.055em] art:text-4xl art:font-medium">
      {lines.map((line, lineIndex) => (<span key={line.join(" ")} className="art:block">
          {line.map((word, wordIndex) => {
                const index = lines.slice(0, lineIndex).reduce((sum, l) => sum + l.length, 0) + wordIndex;
                return (<motion.span key={word} className="art:inline-block art:will-change-transform" initial={WORD_HIDDEN} animate={inView || reduce ? WORD_SHOWN : WORD_HIDDEN} transition={reduce ? INSTANT : wordTransition(index)}>
                {word}
                {wordIndex < line.length - 1 ? (<span className="art:inline-block art:w-[0.25em] art:overflow-hidden">{"\u00A0"}</span>) : null}
              </motion.span>);
            })}
        </span>))}
    </h2>);
}
function StepCard({ step, index, active, onSelect }: {
    step: ArtemisHowItWorksStep;
    index: number;
    active: boolean;
    onSelect: () => void;
}) {
    const Icon: ComponentType<{ className?: string; strokeWidth?: number }> = step.icon ?? ICONS[index % ICONS.length];
    const Scene = SCENES[index % SCENES.length];
    const reduce = useReducedMotion();
    return (<motion.article className="art:relative art:grid art:min-w-0 art:grid-rows-[13rem_auto] art:border-border/70 art:border-b art:transition-colors art:duration-500 art:last:border-b-0 art:@min-[768px]/artemis:grid-rows-[15rem_auto] art:@min-[768px]/artemis:border-r art:@min-[768px]/artemis:border-b-0 art:@min-[768px]/artemis:last:border-r-0 art:bg-background" initial={{ opacity: 0, filter: "blur(6px)" }} whileInView={{ opacity: 1, filter: "blur(0px)" }} viewport={{ once: true, margin: "-50px" }} transition={reduce ? INSTANT : { duration: 0.55, ease: ARTEMIS_EASE_OUT, delay: index * 0.06 }}>
      <div className="art:relative art:overflow-hidden art:border-border/70 art:border-b">
        <div aria-hidden="true" className="art:absolute art:inset-0 art:bg-[radial-gradient(circle_at_50%_0%,hsl(var(--artemis-foreground)/0.07),transparent_58%)]"/>
        <div aria-hidden="true" className="art:absolute art:inset-0 art:p-5 art:@min-[640px]/artemis:p-6">
          <Scene active={active}/>
        </div>
      </div>
      <ArtemisButton variant="link" size="none" className="art:h-auto art:font-normal art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:flex art:min-h-[14rem] art:w-full art:flex-col art:p-6 art:text-left art:outline-none art:transition-colors art:focus-visible:bg-muted/60 art:@min-[640px]/artemis:p-7 art:@min-[768px]/artemis:min-h-[15rem]" aria-pressed={active} onClick={onSelect}>
        <span className="art:flex art:w-full art:items-center art:justify-between">
          <span className="art:font-medium art:text-muted-foreground art:text-xs art:tabular-nums">{stepNumber(index)}</span>
          <span className={artemisCx("art:grid art:size-9 art:place-items-center art:rounded-full art:transition-colors art:duration-300", active ? "art:bg-foreground art:text-background" : "art:bg-muted art:text-muted-foreground")}>
            <Icon strokeWidth={1.7} className="art:size-4"/>
          </span>
        </span>
        <span className="art:mt-8 art:font-medium art:text-muted-foreground art:text-xs art:uppercase art:tracking-[0.15em]">{step.label}</span>
        <h3 className="art:mt-3 art:text-balance art:font-medium art:text-xl art:leading-[1.04] art:tracking-[-0.04em]">{step.title}</h3>
        <p className="art:mt-4 art:max-w-sm art:text-pretty art:text-muted-foreground art:text-sm art:leading-6">{step.description}</p>
      </ArtemisButton>
    </motion.article>);
}
export default function HowItWorksProcessGrid({ content }: { content?: Partial<ArtemisHowItWorksContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const sectionRef = useRef<HTMLElement>(null);
    const headerRef = useRef<HTMLDivElement>(null);
    const sectionInView = useInView(sectionRef);
    const headerInView = useInView(headerRef, { once: true, amount: 0.25 });
    const reduce = useReducedMotion();
    const [active, setActive] = useState(0);
    useEffect(() => {
        if (!sectionInView)
            return;
        const timer = window.setTimeout(() => setActive((current) => (current + 1) % copy.steps.length), AUTOPLAY_MS);
        return () => window.clearTimeout(timer);
    }, [active, sectionInView]);
    return (<section ref={sectionRef} className="art:w-full art:overflow-hidden art:bg-background art:px-4 art:py-20 art:text-foreground art:@min-[640px]/artemis:px-6 art:@min-[640px]/artemis:py-24 art:@min-[1024px]/artemis:px-8 art:@min-[1024px]/artemis:py-28">
      <div className="art:mx-auto art:w-full art:max-w-7xl">
        <div ref={headerRef} className="art:grid art:items-end art:gap-8 art:@min-[1024px]/artemis:grid-cols-[1.25fr_0.75fr] art:@min-[1024px]/artemis:gap-16">
          <div>
            <motion.span className="art:inline-flex art:rounded-full art:border art:border-border/70 art:bg-background art:px-3 art:py-1.5 art:font-medium art:text-muted-foreground art:text-xs" initial={{ opacity: 0, transform: "translate3d(0,8px,0)" }} whileInView={{ opacity: 1, transform: "translate3d(0,0,0)" }} viewport={{ once: true, margin: "-50px" }} transition={reduce ? INSTANT : { duration: 0.45, ease: ARTEMIS_EASE_OUT }}>
              {copy.badge}
            </motion.span>
            <Heading text={copy.headline}/>
          </div>
          <motion.div className="art:max-w-xl art:@min-[1024px]/artemis:justify-self-end" initial={COPY_HIDDEN} animate={headerInView || reduce ? COPY_SHOWN : COPY_HIDDEN} transition={reduce ? INSTANT : { duration: 0.55, ease: ARTEMIS_EASE_OUT, delay: 0.28 }}>
            <p className="art:text-pretty art:text-muted-foreground art:text-sm art:leading-6 art:@min-[640px]/artemis:text-base art:@min-[640px]/artemis:leading-7">
              {copy.subhead}
            </p>
            <ArtemisButtonLink href={copy.cta.href} variant="secondary" size="md" className="art:mt-6 art:w-fit art:h-9">
              {copy.cta.label}
              <ArrowRight className="art:size-4"/>
            </ArtemisButtonLink>
          </motion.div>
        </div>
        <div className="art:relative art:mt-14 art:border art:border-border/70 art:@min-[640px]/artemis:mt-16">
          <span aria-hidden="true" className={artemisCx(CORNER, "art:-top-2 art:-left-2")}/>
          <span aria-hidden="true" className={artemisCx(CORNER, "art:-top-2 art:-right-2")}/>
          <span aria-hidden="true" className={artemisCx(CORNER, "art:-bottom-2 art:-left-2")}/>
          <span aria-hidden="true" className={artemisCx(CORNER, "art:-right-2 art:-bottom-2")}/>
          <div className="art:grid art:@min-[768px]/artemis:grid-cols-3">
            {copy.steps.map((step, index) => (<StepCard key={stepNumber(index)} step={step} index={index} active={active === index} onSelect={() => setActive(index)}/>))}
          </div>
        </div>
      </div>
    </section>);
}

"use client";
// @zeus-internal
import { Check, ClipboardPenLine, Layers, MessageSquareText, MicVocal, Sparkles } from "lucide-react";
import { motion } from "motion/react";
import { ARTEMIS_EASE_OUT } from "../../../../lib/ease";
import { artemisCx } from "../../../../lib/utils";
const SHOWN = "translate3d(0,0,0)";
function captureRow(index: number, active: boolean) {
    return {
        animate: active
            ? { opacity: 1, transform: SHOWN }
            : { opacity: 0.55, transform: `translate3d(${index === 0 ? -14 : 14}px,0,0)` },
        transition: { duration: 0.45, ease: ARTEMIS_EASE_OUT, delay: active ? index * 0.08 : 0 },
    } as const;
}
export function CaptureScene({ active }: {
    active: boolean;
}) {
    return (<div className="art:mx-auto art:flex art:max-w-xs art:flex-col art:gap-2">
      <motion.div className="art:flex art:items-center art:gap-3 art:border art:border-border/70 art:bg-background/70 art:px-3.5 art:py-3 art:backdrop-blur-md" {...captureRow(0, active)}>
        <span className="art:grid art:size-8 art:place-items-center art:rounded-full art:bg-muted art:text-muted-foreground">
          <MessageSquareText strokeWidth={1.7} className="art:size-3.5"/>
        </span>
        <span className="art:font-medium art:text-xs">Customer note</span>
        <span className="art:ml-auto art:text-muted-foreground art:text-xs art:uppercase art:tracking-[0.12em]">Added</span>
      </motion.div>
      <motion.div className="art:flex art:items-center art:gap-3 art:border art:border-border/70 art:bg-background/70 art:px-3.5 art:py-3 art:backdrop-blur-md" {...captureRow(1, active)}>
        <span className="art:grid art:size-8 art:place-items-center art:rounded-full art:bg-muted art:text-muted-foreground">
          <MicVocal strokeWidth={1.7} className="art:size-3.5"/>
        </span>
        <span className="art:font-medium art:text-xs">Voice memo</span>
        <span className="art:ml-auto art:text-muted-foreground art:text-xs art:uppercase art:tracking-[0.12em]">Added</span>
      </motion.div>
      <motion.div className="art:mt-2 art:border art:border-border/70 art:bg-background art:px-4 art:py-3.5" animate={active ? { clipPath: "inset(0%)", opacity: 1 } : { clipPath: "inset(0% 100% 0% 0%)", opacity: 0.38 }} transition={{ duration: 0.65, ease: ARTEMIS_EASE_OUT, delay: active ? 0.22 : 0 }}>
        <div className="art:flex art:items-center art:gap-3">
          <ClipboardPenLine strokeWidth={1.7} className="art:size-4 art:text-muted-foreground"/>
          <span className="art:font-medium art:text-xs">Focused product brief</span>
        </div>
      </motion.div>
    </div>);
}
const PLAN_ROWS = [
    { title: "Confirm the outcome", meta: "Decision" },
    { title: "Assign the owner", meta: "Ownership" },
    { title: "Define the next move", meta: "Action" },
] as const;
export function ShapeScene({ active }: {
    active: boolean;
}) {
    return (<div className="art:mx-auto art:max-w-xs art:border art:border-border/70 art:bg-background/70 art:p-3 art:backdrop-blur-md">
      <div className="art:flex art:items-center art:justify-between art:border-border/70 art:border-b art:px-1 art:pb-3">
        <span className="art:font-medium art:text-xs">Working plan</span>
        <Layers strokeWidth={1.7} className="art:size-3.5 art:text-muted-foreground"/>
      </div>
      <div className="art:mt-3 art:space-y-2">
        {PLAN_ROWS.map((row, index) => (<motion.div key={row.title} className="art:flex art:items-center art:gap-3 art:border art:border-border/65 art:bg-background art:px-3 art:py-2.5" animate={active
                ? { opacity: 1, transform: SHOWN }
                : { opacity: 0.55, transform: `translate3d(${index % 2 === 0 ? -12 : 12}px,0,0)` }} transition={{ duration: 0.45, ease: ARTEMIS_EASE_OUT, delay: active ? index * 0.07 : 0 }}>
            <span className={artemisCx("art:grid art:size-6 art:place-items-center art:rounded-full art:border art:transition-colors art:duration-300", active ? "art:border-foreground art:bg-foreground art:text-background" : "art:border-border art:text-muted-foreground")}>
              <Check className="art:size-3"/>
            </span>
            <span className="art:min-w-0">
              <span className="art:block art:truncate art:font-medium art:text-xs">{row.title}</span>
              <span className="art:mt-0.5 art:block art:text-muted-foreground art:text-xs">{row.meta}</span>
            </span>
          </motion.div>))}
      </div>
    </div>);
}
export function ShipScene({ active }: {
    active: boolean;
}) {
    return (<div className="art:mx-auto art:max-w-xs art:border art:border-border/70 art:bg-background/70 art:p-4 art:backdrop-blur-md">
      <div className="art:flex art:items-center art:justify-between">
        <div>
          <p className="art:font-medium art:text-muted-foreground art:text-xs art:uppercase art:tracking-[0.14em]">Release</p>
          <p className="art:mt-1.5 art:font-medium art:text-sm">Workspace update 2.4</p>
        </div>
        <span className="art:rounded-full art:border art:border-border/70 art:bg-background art:px-2.5 art:py-1 art:font-medium art:text-xs">Ready</span>
      </div>
      <motion.div className="art:mt-6 art:flex art:items-center art:gap-3 art:border art:border-border/70 art:bg-background art:px-3.5 art:py-3" animate={active ? { opacity: 1, transform: SHOWN } : { opacity: 0.48, transform: "translate3d(0,12px,0)" }} transition={{ duration: 0.5, ease: ARTEMIS_EASE_OUT, delay: active ? 0.28 : 0 }}>
        <span className="art:grid art:size-8 art:place-items-center art:rounded-full art:bg-foreground art:text-background">
          <Check className="art:size-4"/>
        </span>
        <span>
          <span className="art:block art:font-medium art:text-xs">Published</span>
          <span className="art:mt-0.5 art:block art:text-muted-foreground art:text-xs">The team can see it now</span>
        </span>
        <Sparkles strokeWidth={1.7} className="art:ml-auto art:size-3.5 art:text-muted-foreground"/>
      </motion.div>
    </div>);
}
